public static void AddFilterField(MethodName _filterName, Name _filterFieldName, ExtendedDataTypeName _EDTBasedOn)
{
    TFMFilterAdditions filterAdditions;
    ttsbegin;
    select forupdate filterAdditions where filterAdditions.FilterName == _filterName && filterAdditions.FilterFieldName == _filterFieldName;

    if(filterAdditions && filterAdditions.RecId)
    {
        filterAdditions.EDTBasedOn = _EDTBasedOn;
        filterAdditions.write();
    } 
    else
    {
        filterAdditions.FilterName = _filterName;
        filterAdditions.FilterFieldName = _filterFieldName;
        filterAdditions.EDTBasedOn = _EDTBasedOn;
        filterAdditions.insert();
    }
    ttscommit;

}

public static boolean exist(MethodName _filterName, Name _filterFieldName)
{
    TFMFilterAdditions filterAdditions;

    select firstonly filterAdditions where filterAdditions.FilterName == _filterName && filterAdditions.FilterFieldName == _filterFieldName;

    return filterAdditions.recid;
}

    public static void deleteFilterField(MethodName _filterName, Name _filterFieldName)
    {
        TFMFilterAdditions				filterAdditions;
        TFMFilterAdditionsDataBinding	dataBinding;
        TFMFilterFieldValues			fieldValues;
        ttsbegin;
        select firstonly forupdate filterAdditions where filterAdditions.FilterName == _filterName && filterAdditions.FilterFieldName == _filterFieldName;
		if (filterAdditions.recId)
        {
            filterAdditions.delete();

            delete_from dataBinding where dataBinding.FilterName == filterAdditions.FilterName && dataBinding.FilterFieldName == filterAdditions.FilterFieldName;
            delete_from fieldValues where fieldValues.FilterName == filterAdditions.FilterName && fieldValues.FilterFieldName == filterAdditions.FilterFieldName;

        }
        ttscommit;
    }

public static void addToFilter(MethodName _filterName, TFMReferenceDataConfiguration _config)
{
    TFMFilterAdditions			filterAdditions;
    TFMRegistrationCollector	collector;

    while select filterAdditions where filterAdditions.FilterName == _filterName && filterAdditions.EDTBasedOn && _filterName
    {
        collector = TFMRegistrationCollector::collectorFromEDT(filterAdditions.EDTBasedOn);

        TFMFilterFieldValues::addSavedValuesToCollector(_filterName,filterAdditions.FilterFieldName,collector);

        _config.addCollector(collector);
    }
}
